package ociresources

import (
	"log"
	"strings"

	tea "charm.land/bubbletea/v2"
	"charm.land/lipgloss/v2"

	"github.com/anthnel/devdesk/internal/imagesearch"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/indicator"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// searchRow is one line of the level 1 table: an image, and the label of the
// registry that returned it.
type searchRow struct {
	img   imagesearch.Image
	label string
}

// searchColumns describes the level 1 table. Minimal for now: the full screen
// (Stars, Official, Description) comes later.
func searchColumns() []datatable.Column[searchRow] {
	return []datatable.Column[searchRow]{
		datatable.IndicatorColumn(
			func(searchRow) indicator.State { return indicator.Idle },
			func(searchRow) string { return theme.IconDocker },
			func(searchRow) lipgloss.Style { return theme.IconStyle(theme.IconRoleImage) },
		),
		{
			Title: "Name", Sizing: datatable.SizingContent, MinWidth: 24, Flex: 1,
			Cell:   func(r searchRow) string { return r.img.Name },
			Search: func(r searchRow) string { return r.img.Name },
		},
		{
			Title: "Registry", Sizing: datatable.SizingContent, MinWidth: 16,
			Cell: func(r searchRow) string { return r.label },
		},
	}
}

// newSearchTable builds the level 1 table, in arrival order (no sort).
func newSearchTable() *datatable.Model[searchRow] {
	t := datatable.New(datatable.Config[searchRow]{
		Columns:    searchColumns(),
		SortColumn: -1,
	})
	return &t
}

// rebuildSearchTable hands the collected images to the table.
func (b *RegistryBrowser) rebuildSearchTable() {
	rows := make([]searchRow, len(b.images))
	for i, img := range b.images {
		label := ""
		if e := b.entryFor(img.EntryKey); e != nil {
			label = e.Alias
			if label == "" {
				label = e.URL
			}
		}
		rows[i] = searchRow{img: img, label: label}
	}
	b.searchTable.SetItems(rows)
	b.searchTable.Resize(b.width+2, max(b.height, 1))
}

// AddImageResults takes one registry's answer. It returns false, touching
// nothing, when the answer belongs to another lot. pendingSearches never goes
// below zero.
func (b *RegistryBrowser) AddImageResults(msg ImageSearchResultMsg) bool {
	if msg.Gen != b.gen {
		return false
	}
	if b.pendingSearches > 0 {
		b.pendingSearches--
	}
	if msg.Err == nil {
		for _, img := range msg.Images {
			img.EntryKey = msg.EntryKey
			b.images = append(b.images, img)
		}
	}
	b.rebuildSearchTable()
	return true
}

// handleImagesKeyMsg handles the keys of the level 1 table. esc goes back to
// the form and drops the lot: its late answers are no longer wanted.
func (b *RegistryBrowser) handleImagesKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
	if msg.String() == "esc" {
		b.cancelInFlight()
		b.gen = nextBrowserGen()
		b.pendingSearches = 0
		b.state = browserStateInput
		b.searchTable.Blur()
		b.updateFocus()
		return b, nil
	}
	return b, b.searchTable.Update(msg)
}

// handleImageSearchResult records one registry's answer; a stale one is ignored.
func (m Model) handleImageSearchResult(msg ImageSearchResultMsg) (tea.Model, tea.Cmd) {
	if m.registryBrowser == nil || !m.registryBrowser.AddImageResults(msg) {
		return m, nil
	}
	if msg.Err != nil {
		alias := msg.EntryKey
		if e := m.registryBrowser.entryFor(msg.EntryKey); e != nil {
			alias = entryAlias(*e)
		}
		log.Printf("ERROR [oci_resources] image search on %s: %s", alias, jobs.SafeCause(msg.Err))
	}
	return m, nil
}

// handleRegistryBrowserWarn shows the browser's warning in the footer.
func (m Model) handleRegistryBrowserWarn(msg RegistryBrowserWarnMsg) (tea.Model, tea.Cmd) {
	return m, m.footer.Warn(strings.TrimSpace(msg.Text))
}
package ociresources

import (
	"context"
	"sync/atomic"
	"time"

	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/imagesearch"
	"github.com/anthnel/devdesk/internal/oci"
)

// browserGen numbers the lots of tag requests across every browser instance,
// so an answer from a browser closed and reopened since is never taken for the
// open one's. Zero is never handed out: it means "no lot".
var browserGen atomic.Uint64

// listRegistryTags is the seam the tag search reads a registry through; tests
// swap it.
var listRegistryTags = oci.ListRegistryTagsContext

// nextBrowserGen returns a fresh generation. Called from Update only (Rule 110).
func nextBrowserGen() uint64 { return browserGen.Add(1) }

// beginRequests cancels the lot in flight and opens a new one: a new
// generation, a fresh context, no pending search. Call it only once a request
// is certain to start, so a refused validation leaves the running lot alone.
func (b *RegistryBrowser) beginRequests() context.Context {
	b.cancelInFlight()
	ctx, cancel := context.WithCancel(context.Background())
	b.cancel = cancel
	b.gen = nextBrowserGen()
	b.pendingSearches = 0
	return ctx
}

// cancelInFlight cancels the lot's context, if any. Nil-safe.
func (b *RegistryBrowser) cancelInFlight() {
	if b == nil || b.cancel == nil {
		return
	}
	b.cancel()
	b.cancel = nil
}

// RegistryBrowserGen returns the generation the open browser accepts, 0 when it
// is closed. For tests, like ActivityTables.
func (m Model) RegistryBrowserGen() uint64 {
	if m.registryBrowser == nil {
		return 0
	}
	return m.registryBrowser.gen
}

// defaultImageSearcher is what a browser opens with. It is nil in production:
// level 1 stays off until an adapter exists, and a short name keeps listing
// tags. Tests inject one before opening the browser.
var defaultImageSearcher imagesearch.Searcher

// imageSearchDeadline bounds one registry's whole search.
var imageSearchDeadline = 15 * time.Second

// targetFor describes entry for the Searcher, with the same alias, address and
// credentials (D12) the tag flow uses.
func (b *RegistryBrowser) targetFor(entry browserRegistryEntry) imagesearch.Target {
	user, pass := b.credsFor(entry)
	return imagesearch.Target{
		EntryKey: entry.key, Alias: entryAlias(entry), RegistryURL: entry.URL,
		APIURL: registryAPIURL(entry.URL), RepoPrefix: entry.repoPrefix,
		Username: user, Password: pass,
	}
}

// startImageSearch opens a lot and asks the Searcher once per entry.
func (b *RegistryBrowser) startImageSearch(query string, entries []browserRegistryEntry) (*RegistryBrowser, tea.Cmd) {
	ctx := b.beginRequests()
	b.images = nil
	b.searchTable.SetItems(nil)

	cmds := make([]tea.Cmd, 0, len(entries))
	for _, entry := range entries {
		b.pendingSearches++
		cmds = append(cmds, searchImagesCmd(ctx, b.gen, b.targetFor(entry), imagesearch.Query{Text: query}, b.searcher))
	}
	b.state = browserStateImages
	b.searchTable.Focus()
	return b, tea.Batch(cmds...)
}

// searchImagesCmd runs one registry's search under imageSearchDeadline, inside
// the lot's context. It reads no model state (Rule 110).
func searchImagesCmd(parent context.Context, gen uint64, t imagesearch.Target, q imagesearch.Query, s imagesearch.Searcher) tea.Cmd {
	return func() tea.Msg {
		ctx, cancel := context.WithTimeout(parent, imageSearchDeadline)
		defer cancel()
		images, partial, err := s.Search(ctx, t, q)
		return ImageSearchResultMsg{Gen: gen, EntryKey: t.EntryKey, Images: images, Partial: partial, Err: err}
	}
